# whrther the array is Sorted or Not 

a=[2,3,1,4,4,5]

def sort(arr,index) :
    if index == len(arr) - 1 :
        return True 
    return arr[index] < arr[index+1] and sort(arr,index+1)


print(sort([1,2,4,8,9,12],0))

# LinerSearch 

def linearSearch(arr,target,index) : 
    if index == len(arr) :
        return -1 
    if arr[index] == target :
        return index 
    else :
        return linearSearch(arr,target,index+1)
def linearSearchLast(arr,target,index) : 
    if index == -1 :
        return -1 
    if arr[index] == target :
        return index 
    else :
        return linearSearchLast(arr,target,index-1)
        
print(linearSearch([1,2,4,8,9,12],9,0))
print(linearSearchLast([1,2,4,8,9,12],9,5))

# [3,4] target = 4
arr=[1,2,3,4,4,8]
def findAll(arr,target,index,l) :  
    if index == len(arr) : 
        return l 
    if target == arr[index] : 
        l.append(index) #**** if ref var may Change , but they pointing to same Object
    return findAll(arr,target,index+1,l)

print(findAll(arr,4,0,[]))


