def findAll2(arr,target,index) :  
    l1=[]  # Every have Its new List 
    if index == len(arr) : 
        return l1
    if target == arr[index] :  # tis will get answer only for that fn call
        l1.append(index)

    answer=findAll2(arr,target,index+1) # add Answer form Before Call
    l1.extend(answer)
    return l1


print(findAll2([1,2,3,4,4,8],4,0))




